-- =====================================================
-- 口說題庫：從既有的 IELTS 題庫匯入 1945 題
--
-- 🔴 這份 SQL 要執行兩次：先在 gsat-staging 執行並確認，再在 production 執行。
-- 🔴 必須在 fix_speaking_part2_cue_optional.sql 之後執行。
--    （下面有檢查會擋下來，不會讓你匯到一半才發現。）
--
--
-- 來源
--
--   ieltscoach-dashboard 的 Supabase 專案，speaking_prompts 表，
--   只取 is_active 的題目。腳本由該專案的 SQL Editor 產生（純 SELECT，
--   沒有動到那邊任何東西）。
--
--   Part 1   801 題
--   Part 2   101 題
--   Part 3  1043 題
--
--
-- 匯入時做了三件事
--
--   1. 【保留原本的 id】。所以 ON CONFLICT (id) DO NOTHING 讓這份檔案
--      可以重複執行，也還追得回舊系統的哪一題。
--
--   2. 【[[BR]] 換成真正的換行】。舊系統用 CSV 批次匯入，儲存格裡的換行
--      被存成字面字串 `[[BR]]`，讀取時才在前端還原。直接搬過來的話，
--      gsat 的畫面上會出現 `[[BR]]` 這五個字。
--
--   3. 【sort_order 依 topic 重編】。舊資料整批都是 0，照那樣進來，
--      同一個主題的題目不會排在一起（例如「Daily routines」那 8 題會散開）。
--
--
-- 為什麼 cue 整欄是空的
--
--   舊系統的 Part 2 題卡根本沒用到 cue —— 「You should say:」是畫面上寫死的
--   一行字，不是題目的一部分（見 csvToPrompts 裡寫死的 `cue: null`）。
--   gsat 這邊跟著這個事實走：cue 選填，空的時候由畫面補那句。
--
--
-- ⚠️ 檔案很大（約 380 KB）。SQL Editor 貼不下的話，下面每一段
--    `-- ── 批次 n/10 ──` 底下的 INSERT 都是獨立可執行的，可以分段貼。
--
-- 回滾：supabase/migrations/seed_speaking_prompts.rollback.sql
-- =====================================================

-- 🛑 先確認 Part 2 的 CHECK 已經放寬。沒放寬的話，這裡的 101 題 Part 2
--    會在中途整批失敗 —— 與其讓它跑到一半爆掉，不如現在就說清楚。
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conname = 'speaking_prompts_part_shape'
  ) THEN
    RAISE EXCEPTION '找不到 speaking_prompts_part_shape，請先套用 create_speaking_prompts.sql';
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conname = 'speaking_prompts_part_shape'
       AND pg_get_constraintdef(oid) LIKE '%cue%'
  ) THEN
    RAISE EXCEPTION
      'Part 2 的 cue 還是必填，這批題目的 cue 全部是空的。請先執行 fix_speaking_part2_cue_optional.sql';
  END IF;
END;
$$;


-- ── 批次 1/10（200 題）──
ON CONFLICT (id) DO NOTHING;

-- ── 批次 2/10（200 題）──
ON CONFLICT (id) DO NOTHING;

-- ── 批次 3/10（200 題）──
ON CONFLICT (id) DO NOTHING;

-- ── 批次 4/10（200 題）──
ON CONFLICT (id) DO NOTHING;

-- ── 批次 5/10（200 題）──
ON CONFLICT (id) DO NOTHING;

-- ── 批次 6/10（200 題）──
ON CONFLICT (id) DO NOTHING;

-- ── 批次 7/10（200 題）──
ON CONFLICT (id) DO NOTHING;

-- ── 批次 8/10（200 題）──
ON CONFLICT (id) DO NOTHING;

-- ── 批次 9/10（200 題）──
ON CONFLICT (id) DO NOTHING;

-- ── 批次 10/10（145 題）──
ON CONFLICT (id) DO NOTHING;


-- =====================================================
-- 驗證：執行完看這張表
-- =====================================================
SELECT part,
       count(*)                                        AS 題數,
       count(*) FILTER (WHERE is_active)               AS 啟用中,
       count(DISTINCT topic) FILTER (WHERE topic IS NOT NULL) AS 主題數
  FROM speaking_prompts
 GROUP BY part
 ORDER BY part;
